import { execFileSync } from 'node:child_process';
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createContext, runInContext } from 'node:vm';
import { describe, expect, it } from 'vitest';

/* V1 story lines (audio/lines/lines.js, GENERATED by tools/story-lines.mjs from the concept folder's voice
   script). No browser: the table runs in a Node vm. The e2e side is tests/e2e/v1-voice-story.spec.ts. */
const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
type Line = [string, string, number, string | null];
type Story = { lines: Record<string, Line>; intro: Record<string, string[]>; exit: Record<string, string[]>; open: Record<string, string[]>;
  clear: Record<string, string[]>; joke: Record<string, string>; bark: Record<string, string[]>; cutscene: string[]; escape: Record<string, string[]> };
const ctx: Record<string, unknown> = {}; ctx.self = ctx; createContext(ctx);
runInContext(readFileSync(join(ROOT, 'audio', 'lines', 'lines.js'), 'utf8'), ctx);
runInContext(readFileSync(join(ROOT, 'audio', 'dad-lines.js'), 'utf8'), ctx);   /* the game plays lines.js with Dad's joke pass over it (2026-10-29) */
const S = ctx.KINAN_STORY as Story, FILES = ctx.KINAN_STORY_FILES as string[];
const html = readFileSync(join(ROOT, 'index.html'), 'utf8');
const ARENA = new Set([...(/const ARENA_LINES = \{([\s\S]*?)\n\};/.exec(html)![1]).matchAll(/^\s+([a-z0-9_]+):\s*\[/gm)].map((m) => m[1]));
const SRC = 'C:/Users/SHADHUNTER/Desktop/Kinan vs Mom/Map Concept/voices/lines';

describe('the story line table', () => {
  it('is what tools/story-lines.mjs writes today (when the voice script is on this machine)', () => {
    if (!existsSync(join(SRC, 'manifest.json'))) return;   /* another machine: the concept folder is not there */
    const out = execFileSync(process.execPath, [join(ROOT, 'tools', 'story-lines.mjs'), '--check', SRC], { encoding: 'utf8' });
    expect(out).toContain('is up to date');
  });
  it('every line it plays exists; every clip is on disk; Worlds 1-5 each have an intro and every exit up to World 5', () => {
    const used = [...Object.values(S.intro), ...Object.values(S.exit), ...Object.values(S.open), ...Object.values(S.clear), Object.values(S.joke), ...Object.values(S.bark)].flat();
    for (const id of used) expect(S.lines[id], id).toBeTruthy();
    for (const id of Object.keys(S.lines)) { const f = S.lines[id][3]; if (f) expect(existsSync(join(ROOT, f)), f).toBe(true); }
    expect(Object.keys(S.intro).sort()).toEqual(['1', '2', '3', '4', '5']);
    expect(Object.keys(S.exit).sort()).toEqual(['1', '2', '3', '4', '5']);
    expect(Object.keys(S.open).length).toBe(49);
  });
  it('C1 (2026-10-28): the opening cutscene plays nine lines in order, each a clip in the picked voices; Worlds 6-9 carry their exit lines for the castle escape', () => {
    expect(S.cutscene).toEqual(['w01_kinan_19', 'w01_shad_05', 'w01_kinan_02', 'w01_glitchy_01', 'w01_kinan_03', 'w01_mom_12', 'w01_glitchy_02', 'gen_kinan_24', 'w01_kinan_20']);
    for (const id of [...S.cutscene, ...Object.values(S.escape).flat()]) {
      expect(S.lines[id], id).toBeTruthy();
      expect(S.lines[id][3], id).toMatch(/^audio\/(lines|rerecord)\/.+\.mp3$/);   /* rerecord: Dad's joke versions, 2026-10-29 */
      expect(existsSync(join(ROOT, S.lines[id][3]!)), id).toBe(true);
      expect(FILES, id).toContain(S.lines[id][3]);   /* precached: the cutscenes talk offline */
    }
    expect(S.lines.w01_shad_05.slice(0, 2)).toEqual(['SHAD', "Don't open this until I get there!"]);
    expect(S.lines.w01_mom_12.slice(0, 2)).toEqual(['MOM', 'Kinan, NO!']);
    expect(Object.keys(S.escape).sort()).toEqual(['6', '7', '8', '9']);
  });
  it('a line a boss arena speaks is never an opener, a LEVEL CLEAR line or a joke (the fight says it)', () => {
    for (const id of [...Object.values(S.open), ...Object.values(S.clear), Object.values(S.joke)].flat()) expect(ARENA.has(id), id).toBe(false);
  });
  it('the subtitles are plain English with a speaker; Robin speaks as DAD', () => {
    for (const [id, l] of Object.entries(S.lines)) {
      expect(l[0], id).toMatch(/^[A-Z ]+$/);
      expect(l[1].length, id).toBeGreaterThan(2);
      expect(l[2], id).toBeGreaterThan(1);
      if (/_robin_\d/.test(id) || id.startsWith('jk_')) expect(l[0], id).toBe('DAD');
    }
    expect(S.lines.w04_annie_pa01[1]).not.toMatch(/Rabba/);
    expect(S.lines.w05_annie_pa01[1]).not.toMatch(/Chheti/);
  });
});

describe('the offline cache (sw.js) carries the Worlds 1-5 story lines', () => {
  const sw = readFileSync(join(ROOT, 'sw.js'), 'utf8');
  it('imports the table and precaches every clip it plays, plus the boss clips in audio/voice/', () => {
    expect(sw).toContain("importScripts('./audio/lines/lines.js');");
    expect(sw).toContain(".concat((self.KINAN_STORY_FILES || []).map((f) => './' + f))");
    expect(sw).toContain("'./audio/lines/lines.js'");
    const clips = [...new Set(Object.values(S.lines).map((l) => l[3]).filter((f): f is string => !!f))];
    for (const f of clips) expect(FILES, f).toContain(f);
    const voice = readdirSync(join(ROOT, 'audio', 'voice')).filter((f) => f.endsWith('.mp3')).map((f) => `audio/voice/${f}`);
    for (const f of voice) expect(FILES, f).toContain(f);
    for (const f of FILES) expect(existsSync(join(ROOT, f)), f).toBe(true);
  });
  it('the story clips stay small (under 8 MB) and the whole precache stays under 30 MB', () => {
    const story = FILES.reduce((n, f) => n + statSync(join(ROOT, f)).size, 0);
    const listed = (src: string): string[] => [...src.matchAll(/'\.\/([^']+)'/g)].map((m) => m[1]);
    const base = listed(/const ASSETS = \[([\s\S]*?)\]/.exec(sw)![1]).filter((f) => f !== '');
    const mapList = listed(/const MAP_FILES = \[([\s\S]*?)\];/.exec(sw)![1]);
    const c: Record<string, unknown> = {}; c.self = c; createContext(c);
    runInContext(readFileSync(join(ROOT, 'levels', 'manifest.js'), 'utf8'), c);
    const levelFiles = (c.KINAN_LEVEL_FILES as string[]).map((f) => `levels/${f}`);
    const all = [...new Set(['index.html', ...base, ...levelFiles, ...mapList, ...FILES])];
    const bytes = all.reduce((n, f) => n + statSync(join(ROOT, f)).size, 0);
    console.log(`story clips: ${FILES.length} files, ${(story / 1048576).toFixed(2)} MB · whole precache: ${all.length} files, ${(bytes / 1048576).toFixed(2)} MB`);
    expect(story).toBeLessThan(8 * 1048576);
    expect(bytes).toBeLessThan(30 * 1048576);
  });
});
